PRAGMA recursive_triggers=OFF; CREATE TEMPORARY TABLE tbl(a INTEGER PRIMARY KEY,b); INSERT INTO tbl VALUES(100,100); INSERT INTO tbl VALUES(300,200); CREATE TEMP TRIGGER delete_before_row BEFORE DELETE ON tbl FOR EACH ROW BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),0,0); END; CREATE TEMP TRIGGER delete_after_row AFTER DELETE ON tbl FOR EACH ROW BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),0,0); END; DELETE FROM tbl;